using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using System.Text.RegularExpressions;
namespace VintageCollector.EditorTools {
 // Guard component only. No Unity dependency, launch, creation, deletion or old admission.
 public static class SuppliedArtBuildPolicy {
  public const string Root=Phase5BuildPolicy.Root;
  public const string StageRelative=".artifacts/sa";
  public const string CandidateRelative="Builds/Phase5SuppliedArtWindows";
  static string Full(string p){if(!Path.IsPathRooted(p))throw new ArgumentException("Absolute required");Phase5BuildPolicy.Safe(p);return Path.GetFullPath(p).TrimEnd('\\','/');}
  public static void Boundaries(string current){BoundariesCore(Root,current);}
  // Semantic exact-root injection is exclusively a directly owned offline fixture.
  public static void FixtureBoundaries(string root,string current,string ownedWorkspace){string fixtures=Full(Path.Combine(ownedWorkspace,"fixtures"));if(!string.Equals(Path.GetDirectoryName(Full(root)),fixtures,StringComparison.OrdinalIgnoreCase)||!Full(ownedWorkspace).Equals(Full(Path.Combine(Root,".artifacts/phase5-supplied-art-build-tools")),StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Not owned fixture");BoundariesCore(root,current);}
  static void BoundariesCore(string root,string current){root=Full(root);string stage=Full(Path.Combine(root,StageRelative));if(!string.Equals(Full(current),stage,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Exact NEW stage required, never Root/old/cousin");string output=Full(Path.Combine(root,CandidateRelative));if(File.Exists(output))throw new InvalidOperationException("Candidate file");if(Directory.Exists(output))foreach(string p in Directory.GetFileSystemEntries(output))if(string.Equals(Path.GetFileName(p),"Saves",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Candidate Saves refused by name before attributes or reads");Phase5BuildPolicy.RequireRegularTree(stage);Phase5BuildPolicy.RequireRegularTree(output);if(Directory.Exists(output)&&Directory.GetFileSystemEntries(output).Length>0){string marker=Path.Combine(output,".supplied-art-candidate-owner.txt");if(!File.Exists(marker)||File.ReadAllText(marker)!="supplied-art-exact-source-v1\n"+root.Replace('\\','/')+"\n")throw new InvalidOperationException("Foreign candidate");}}
  public static void ExactClosure(string project,IDictionary<string,string> expected){var actual=Phase5BuildPolicy.AllInputs(project);if(actual.Count!=expected.Count)throw new InvalidOperationException("Full closure membership");foreach(var pin in expected){string d;if(!actual.TryGetValue(pin.Key,out d)||pin.Value!=d)throw new InvalidOperationException("Full closure bytes");}RequireUniqueGuids(project,actual);}
  public static void RequireUniqueGuids(string project,IDictionary<string,string> all){var seen=new HashSet<string>(StringComparer.Ordinal);foreach(string n in all.Keys)if(n.EndsWith(".meta",StringComparison.Ordinal)){string path=Path.Combine(project,n);Phase5BuildPolicy.Safe(path);if(new FileInfo(path).Length>65536)throw new InvalidOperationException("Meta bound");string text=File.ReadAllText(path);var matches=Regex.Matches(text,"(?m)^guid: ([0-9a-f]{32})\\r?$");if(matches.Count!=1||!Regex.IsMatch(text,"(?m)^fileFormatVersion: 2\\r?$")||!seen.Add(matches[0].Groups[1].Value))throw new InvalidOperationException("Invalid/duplicate GUID");}}
  public static void NativeMetaAllowance(string root,string stage,IDictionary<string,string> source,IEnumerable<string> assets){ExactSource(root,source);RequireUniqueGuids(stage,Phase5BuildPolicy.AllInputs(stage));var seen=new HashSet<string>(StringComparer.Ordinal);foreach(string n in assets){if(!seen.Add(n)||!n.StartsWith("Assets/",StringComparison.Ordinal)||n.EndsWith(".meta",StringComparison.Ordinal)||n.Contains("..")||n.Contains("\\")||n.Contains(":")||!source.ContainsKey(n)||source.ContainsKey(n+".meta")||File.Exists(Path.Combine(root,n+".meta")))throw new InvalidOperationException("Unknown/duplicate/existing metadata allowance");if(Regex.IsMatch(File.ReadAllText(Path.Combine(stage,n+".meta")),"(?m)^folderAsset:")||Phase5BuildPolicy.Hash(Path.Combine(stage,n))!=source[n]||!File.Exists(Path.Combine(stage,n+".meta")))throw new InvalidOperationException("Stage source/meta mismatch");}}

  public const string Generation="b98f62fecb5239f3bbc7cf78273c2b8f209488f40d5362ba4519824a419058fb";
  public const string Scene="Assets/VintageCollector/Scenes/BootstrapSuppliedExpansionArt.unity";
  public const string Settings="ProjectSettings/EditorBuildSettings.asset";
  public static byte[] RecipeBytes(string root,string stage){string old=File.ReadAllText(Path.Combine(root,Settings));string meta=File.ReadAllText(Path.Combine(stage,Scene+".meta"));var guid=Regex.Matches(meta,"(?m)^guid: ([0-9a-f]{32})\\r?$");var paths=Regex.Matches(old,"(?m)^    path: (.+?)\\r?$");var guids=Regex.Matches(old,"(?m)^    guid: ([0-9a-f]{32})\\r?$");var enabled=Regex.Matches(old,"(?m)^  - enabled: (.+?)\\r?$");if(guid.Count!=1||paths.Count!=1||paths[0].Groups[1].Value!="Assets/VintageCollector/Scenes/Bootstrap.unity"||guids.Count!=1||enabled.Count!=1||enabled[0].Groups[1].Value!="1")throw new InvalidOperationException("Exact recipe source");return new UTF8Encoding(false,true).GetBytes(old.Replace("    path: "+paths[0].Groups[1].Value,"    path: "+Scene).Replace("    guid: "+guids[0].Groups[1].Value,"    guid: "+guid[0].Groups[1].Value));}
  public static void NativeFolderAllowance(string root,string stage,IDictionary<string,string> source,IEnumerable<string> folders){string gen="Assets/Supplied/ExpansionSetMaterials/generations/"+Generation;var known=new HashSet<string>(new[]{"Assets/Supplied/ExpansionSetMaterials","Assets/Supplied/ExpansionSetMaterials/generations",gen,gen+"/fossil",gen+"/jungle"},StringComparer.Ordinal);var missing=new HashSet<string>(known.Where(n=>Directory.Exists(Path.Combine(root,n))&&!File.Exists(Path.Combine(root,n+".meta"))),StringComparer.Ordinal);var list=folders.ToArray();if(list.Length!=list.Distinct(StringComparer.Ordinal).Count()||!missing.SetEquals(list)||(list.Length>0&&source.Keys.Count(n=>n.StartsWith(gen+"/",StringComparison.Ordinal)&&n.EndsWith(".png",StringComparison.Ordinal))!=132))throw new InvalidOperationException("Exact generation folders");foreach(string n in list){Phase5BuildPolicy.Safe(Path.Combine(root,n));Phase5BuildPolicy.Safe(Path.Combine(stage,n));if(source.ContainsKey(n)||!Directory.Exists(Path.Combine(stage,n))||!source.Keys.Any(a=>a.StartsWith(n+"/",StringComparison.Ordinal)&&a.EndsWith(".png",StringComparison.Ordinal)))throw new InvalidOperationException("Folder role");string text=File.ReadAllText(Path.Combine(stage,n+".meta"));if(!Regex.IsMatch(text,"(?m)^folderAsset: yes\\r?$")||!Regex.IsMatch(text,"(?m)^DefaultImporter:\\r?$"))throw new InvalidOperationException("Folder importer");}}
  // Actual production admission helper: inherited frozen pins remain authoritative; only validated new metadata can extend them.
  public static void AdmitClosure(string root,string stage,IDictionary<string,string> source,IDictionary<string,string> frozen,IEnumerable<string> assets,IEnumerable<string> folders,string action){
   ExactSource(root,source);if(action=="BuildWindows"&&!File.ReadAllBytes(Path.Combine(stage,Settings)).SequenceEqual(RecipeBytes(root,stage)))throw new InvalidOperationException("Exact effective recipe required");var actual=Phase5BuildPolicy.AllInputs(stage);var files=assets.ToArray();var dirs=folders.ToArray();var missing=new HashSet<string>(source.Keys.Where(n=>n.StartsWith("Assets/",StringComparison.Ordinal)&&!n.EndsWith(".meta",StringComparison.Ordinal)&&!source.ContainsKey(n+".meta")),StringComparer.Ordinal);if(files.Length!=files.Distinct(StringComparer.Ordinal).Count()||!missing.SetEquals(files))throw new InvalidOperationException("Every missing file meta required");
   NativeMetaAllowance(root,stage,source,files);NativeFolderAllowance(root,stage,source,dirs);var extras=new HashSet<string>(files.Concat(dirs).Select(n=>n+".meta"),StringComparer.Ordinal);
   foreach(var p in frozen){string d;if(!actual.TryGetValue(p.Key,out d)||d!=p.Value)throw new InvalidOperationException("Frozen stage drift");}
   if(actual.Keys.Any(n=>!frozen.ContainsKey(n)&&!extras.Contains(n)))throw new InvalidOperationException("Unapproved import extra");
   foreach(var p in source){string d;if(!frozen.TryGetValue(p.Key,out d))throw new InvalidOperationException("Missing source");if(d!=p.Value){if(action!="BuildWindows"||p.Key!=Settings||!File.ReadAllBytes(Path.Combine(stage,Settings)).SequenceEqual(RecipeBytes(root,stage)))throw new InvalidOperationException("Source drift");}}
   if(frozen.Keys.Any(n=>!source.ContainsKey(n)))throw new InvalidOperationException("Unapproved frozen extra");if(action=="BuildWindows"&&(files.Length!=0||dirs.Length!=0))throw new InvalidOperationException("Adopt metadata before build");RequireUniqueGuids(stage,actual);
  }
  public static void ExactSource(string root,IDictionary<string,string> source){var actual=Phase5BuildPolicy.AllInputs(root);if(actual.Count!=source.Count)throw new InvalidOperationException("Root membership");foreach(var pin in source){string d;if(!actual.TryGetValue(pin.Key,out d)||d!=pin.Value)throw new InvalidOperationException("Root byte mismatch");}}
 }
}
